theorem creutz_ratio_comparison (beta : Rat) (hb : beta ≠ 0) (hbeta : beta = (1/9 : Rat)) (R T : Nat) (hR : 0 < R) (hT : 0 < T) :
  let wA := FiniteQM.wilson_area_law beta R T;
  let wP := FiniteQM.wilson_perimeter_law beta R T;
  let crA := FiniteQM.creutz_ratio wA (FiniteQM.wilson_area_law beta (R+1) (T+1)) (FiniteQM.wilson_area_law beta R (T+1)) (FiniteQM.wilson_area_law beta (R+1) T);
  let crP := FiniteQM.creutz_ratio wP (FiniteQM.wilson_perimeter_law beta (R+1) (T+1)) (FiniteQM.wilson_perimeter_law beta R (T+1)) (FiniteQM.wilson_perimeter_law beta (R+1) T);
  have hcrA : crA = beta := by sorry;
  have hcrP : crP = 1 := by sorry;
  by
    simpa [hbeta] using And.intro hcrA hcrP
